/* ---------------- JPlayNote (src/pilot/JPlayNote.c) ---------------- */
/* Driver 2: JPlayNote (XMPLAY.C) */
extern XMCHANNEL *XMC;
#define XMC XMC
int JPlayNote(unsigned char *j, int pmsk)
{
    unsigned char b;
    int ret = 1;
    unsigned char note = 0;

    b = *j;

    XMC->eff = 0;
    XMC->vol = 0;
    XMC->dat = 0;

    if (b == 0x80) {
        XMC->nothing = 1;
        return ret;
    }

    j++;

    if ((b & 0x80) != 0) {
        if ((b & 1) != 0) {
            if (pmsk != 0) {
                XMC->nothing = 0;
                note = *j;
                SetNote(note - 1);
            }
            j++;
            ret++;
        }

        if ((b & 2) != 0) {
            if (pmsk != 0) {
                XMC->ins = *j;
                SetInstr(XMC->ins - 1);
            }
            j++;
            ret++;
        }
        if (((b & 3) != 0) && (note != 97) && (pmsk != 0))
            SetPer();

        if ((b & 4) != 0) {
            XMC->nothing = 0;
            XMC->vol = *j;
            j++;
            ret++;
        }

        if ((b & 8) != 0) {
            XMC->nothing = 0;
            XMC->eff = *j;
            j++;
            ret++;
        }
        if ((b & 16) != 0) {
            XMC->dat = *j;
            ret++;
        }
    } else {
        XMC->nothing = 0;
        note = b;

        if (pmsk != 0) {
            SetNote(note - 1);
            XMC->ins = *j;
            SetInstr(XMC->ins - 1);
            if (note != 97)
                SetPer();
            XMC->vol = *(j + 1);
            XMC->eff = *(j + 2);
            XMC->dat = *(j + 3);
        }
        ret = 5;
    }
    return ret;
}
#undef XMC

/* ---------------- JPlayEffects (src/pilot/JPlayEffects.c) ---------------- */
/* JPlayEffects (Driver 2 name) */
void JPlayEffects(void)
{
    unsigned char vol;
    unsigned char eff;
    unsigned char dat;

    vol = XMC->vol;
    eff = XMC->eff;
    dat = XMC->dat;

    XMC->ownper = 0;
    XMC->ownvol = 0;

    switch (vol >> 4) {
    case 0x6:
        if (vol & 0xf)
            SPE(0xa, vol & 0xf);
        break;
    case 0x7:
        if (vol & 0xf)
            SPE(0xa, vol << 4);
        break;
    case 0x8:
        SPE(0xe, 0xb0 | (vol & 0xf));
        break;
    case 0x9:
        SPE(0xe, 0xa0 | (vol & 0xf));
        break;
    case 0xa:
        SPE(0x4, vol << 4);
        break;
    case 0xb:
        SPE(0x4, vol & 0xf);
        break;
    case 0xc:
        XMC->panning = (vol & 0xf) << 4;
        break;
    case 0xd:
        if (vol & 0xf)
            DoXMPanSlide(vol & 0xf);
        break;
    case 0xe:
        if (vol & 0xf)
            DoXMPanSlide(vol << 4);
        break;
    case 0xf:
        SPE(0x3, vol << 4);
        break;
    default:
        if (vol >= 0x10 && vol <= 0x50)
            SPE(0xc, vol - 0x10);
    }

    switch (eff) {
    case 'G' - 55:
        D_00097814->SongVolume = dat * 2;
        break;
    case 'H' - 55:
        break;
    case 'K' - 55:
        SetNote(96);
        break;
    case 'L' - 55:
        break;
    case 'P' - 55:
        XMC->panning = dat;
        break;
    case 'R' - 55:
        DoS3MRetrig(dat);
        break;
    case 'T' - 55:
        SPE(0x6, dat);
        break;
    case 'X' - 55:
        break;
    default:
        if (eff <= 0xf)
            SPE(eff, dat);
        break;
    }

    if (!XMC->ownper)
        XMC->period = XMC->tmpperiod;
    if (!XMC->ownvol)
        XMC->volume = XMC->tmpvolume;
}

