void SPE(unsigned char eff, unsigned char dat)
{
    int hi;
    int lo;

    switch (eff) {
    case 0:
        Arpeggio(dat);
        break;
    case 1:
        if (dat != 0)
            XMC->slidespeed = ((unsigned short)(dat)) << 2;
        if (ms->vbtick)
            XMC->tmpperiod -= XMC->slidespeed;
        break;
    case 2:
        if (dat != 0)
            XMC->slidespeed = (unsigned short)(dat) << 2;
        if (ms->vbtick)
            XMC->tmpperiod += XMC->slidespeed;
        break;
    case 3:
        XMC->kick = 0;
        if (dat != 0) {
            XMC->portspeed = dat;
            XMC->portspeed <<= 2;
        }
        DoToneSlide();
        XMC->ownper = 1;
        break;
    case 4:
        if (dat & 0x0f) XMC->vibdepth = dat & 0x0f;
        if (dat & 0xf0) XMC->vibspd = (dat & 0xf0) >> 2;
        DoVibrato();
        XMC->ownper = 1;
        break;
    case 5:
        XMC->kick = 0;
        DoToneSlide();
        if (dat == 0)
            dat = XMC->oldvslide;
        XMC->oldvslide = dat;
        DoVolSlide(dat);
        XMC->ownper = 1;
        break;
    case 6:
        DoVibrato();
        if (dat == 0)
            dat = XMC->oldvslide;
        XMC->oldvslide = dat;
        DoVolSlide(dat);
        XMC->ownper = 1;
        break;
    case 7:
        if (dat & 0x0f) XMC->trmdepth = dat & 0xf;
        if (dat & 0xf0) XMC->trmspd = (dat & 0xf0) >> 2;
        DoTremolo();
        XMC->ownvol = 1;
        break;
    case 8:
        XMC->panning = dat;
        break;
    case 9:
        if (ms->vbtick)
            break;
        if (dat == 0)
            break;
        XMC->SOffset = dat;
        XMC->SOffset *= 256;
        XMC->SOffset *= 2;
        XMC->SOffset /= 7;
        XMC->SOffset *= 2;
        XMC->SOffset &= (~31);
        break;
    case 0xA:
        if (dat == 0)
            dat = XMC->oldvslide;
        XMC->oldvslide = dat;
        DoVolSlide(dat);
        break;
    case 0xB:
        if (ms->patdly2)
            break;
        ms->patbrk = 0;
        ms->SongPos = dat - 1;
        ms->posjmp = 2;
        break;
    case 0xC:
        if (ms->vbtick)
            break;
        if (dat == 0xff)
            ms->BPlayFlag = 1;
        else if (dat == 0xfe)
            ms->BPlayFlag = 0;
        else if (dat == 0xfd)
            ms->BPlayFlag = 2;
        else if (dat == 0xfc)
            XMC->Dolby = 0;
        else if (dat == 0xfb)
            XMC->Dolby = 1;
        else if (dat == 0xfa)
            XMC->Dolby = 2;
        else {
            if (dat > 64) dat = 64;
            XMC->tmpvolume = dat + 64;
        }
        break;
    case 0xD:
        if (ms->patdly2)
            break;
        hi = (dat & 0xf0) >> 4;
        lo = (dat & 0xf);
        ms->patbrk = ((hi * 10) + lo) + 1;
        if (ms->patbrk > (ms->numrow + 1))
            ms->patbrk = ms->numrow + 1;
        ms->posjmp = 2;
        break;
    case 0xE:
        DoEEffects(dat);
        break;
    case 0xF:
        if (ms->vbtick || ms->patdly2)
            break;
        if (dat < 0x20) {
            ms->SongSpeed = dat;
            ms->vbtick = 0;
        } else {
            ms->SongBPM = dat;
            ms->vbtick = 0;
        }
        break;
    default:
        break;
    }
}
