/* ---------------- DoEEffects (src/pilot/DoEEffects.c) ---------------- */
/* DoEEffects (Driver 2 name) */
extern XMCHANNEL *XMC;
#define ms D_00097814
#define XMC XMC
void DoEEffects(unsigned char dat)
{
    unsigned char nib;

    nib = dat & 0xf;

    switch (dat >> 4) {
    case 0x0:
        break;
    case 0x1:
        if (!ms->vbtick) {
            if (nib == 0)
                nib = XMC->oldfslide;
            XMC->oldfslide = nib;
            XMC->tmpperiod += (nib << 2);
        }
        break;
    case 0x2:
        if (!ms->vbtick) {
            if (nib == 0)
                nib = XMC->oldfslide;
            XMC->oldfslide = nib;
            XMC->tmpperiod -= (nib << 2);
        }
        break;
    case 0x3:
        XMC->glissando = nib;
        break;
    case 0x4:
        XMC->wavecontrol &= 0xf0;
        XMC->wavecontrol |= nib;
        break;
    case 0x5:
        break;
    case 0x6:
        if (ms->vbtick)
            break;
        if (nib) {
            if (ms->repcnt > 0)
                ms->repcnt--;
            else
                ms->repcnt = nib;
            if (ms->repcnt)
                ms->PatternPos = ms->reppos;
        } else {
            ms->reppos = ms->PatternPos - 1;
        }
        break;
    case 0x7:
        XMC->wavecontrol &= 0x0f;
        XMC->wavecontrol |= nib << 4;
        break;
    case 0x8:
        XMC->panning = nib << 4;
        break;
    case 0x9:
        if (nib > 0) {
            if (XMC->retrig == 0) {
                XMC->kick = 1;
                XMC->retrig = nib;
            }
            XMC->retrig--;
        }
        break;
    case 0xA:
        if (ms->vbtick)
            break;
        if (nib == 0)
            nib = XMC->oldfvslide;
        XMC->oldfvslide = nib;
        XMC->tmpvolume += nib;
        if (XMC->tmpvolume > 128)
            XMC->tmpvolume = 128;
        break;
    case 0xB:
        if (ms->vbtick)
            break;
        if (nib == 0)
            nib = XMC->oldfvslide;
        XMC->oldfvslide = nib;
        XMC->tmpvolume -= nib;
        if (XMC->tmpvolume < 64)
            XMC->tmpvolume = 64;
        break;
    case 0xC:
        if (ms->vbtick >= nib)
            XMC->tmpvolume = 64;
        break;
    case 0xD:
        if (ms->vbtick == nib)
            XMC->kick = 1;
        else
            XMC->kick = 0;
        break;
    case 0xE:
        if (ms->vbtick)
            break;
        if (!ms->patdly2)
            ms->patdly = nib + 1;
        break;
    case 0xF:
        break;
    }
}
#undef XMC
#undef ms

