/* ---------------- Arpeggio (src/pilot/Arpeggio.c) ---------------- */
/* Arpeggio (Driver 2) */
void Arpeggio(unsigned char dat)
{
    int note;
    short per; int n;
    unsigned short c;
    note = XMC->note;
    if (dat != 0) {
        switch (D_00097814->vbtick % 3) {
        case 1: note += dat >> 4; break;
        case 2: note += dat & 0xf; break;
        }
        n = note + XMC->transpose;
        c = XMC->c2spd;
        if (D_00097814->NotAmiga == 1) {
            per = 0x1E00 - (short)c / 2;
            per -= (unsigned char)n * 64;
            per += 64;
        } else
            per = func_0006F81C((unsigned char)n, c);
        XMC->period = per;
        XMC->ownper = 1;
    }
}

/* ---------------- DoVolSlide (src/pilot/DoVolSlide.c) ---------------- */
/* Driver 2: DoVolSlide */
void DoVolSlide(unsigned char dat) {
    if (!D_00097814->vbtick) return;
    XMC->tmpvolume += dat >> 4;
    if (XMC->tmpvolume > 128) XMC->tmpvolume = 128;
    XMC->tmpvolume -= dat & 0xf;
    if (XMC->tmpvolume < 64) XMC->tmpvolume = 64;
}

/* ---------------- DoXMPanSlide (src/pilot/DoXMPanSlide.c) ---------------- */
/* Driver 2: DoXMPanSlide */
void DoXMPanSlide(unsigned char inf) {
    unsigned char lo, hi;
    short pan;
    if (inf != 0) XMC->pansspd = inf;
    else inf = XMC->pansspd;
    if (D_00097814->vbtick == 0) return;
    lo = inf & 0xf;
    hi = inf >> 4;
    if (hi) lo = 0;
    pan = XMC->panning;
    pan -= lo;
    pan += hi;
    if (pan < 0) pan = 0;
    if (pan > 255) pan = 255;
    XMC->panning = pan;
}

/* ---------------- DoS3MRetrig (src/pilot/DoS3MRetrig.c) ---------------- */
/* DoS3MRetrig (Driver 2 name) */
void DoS3MRetrig(unsigned char inf)
{
    unsigned char hi, lo;

    hi = inf >> 4;
    lo = inf & 0xf;

    if (lo) {
        XMC->s3mrtgslide = hi;
        XMC->s3mrtgspeed = lo;
    }

    if (hi) {
        XMC->s3mrtgslide = hi;
    }

    if (XMC->s3mrtgspeed > 0) {
        if (XMC->retrig == 0) {
            XMC->kick = 1;
            XMC->retrig = XMC->s3mrtgspeed;

            if (D_00097814->vbtick) {
                switch (XMC->s3mrtgslide) {
                case 1:
                case 2:
                case 3:
                case 4:
                case 5:
                    XMC->tmpvolume -= (1 << (XMC->s3mrtgslide - 1));
                    break;
                case 6:
                    XMC->tmpvolume = (2 * XMC->tmpvolume) / 3;
                    break;
                case 7:
                    XMC->tmpvolume = XMC->tmpvolume >> 1;
                    if (XMC->tmpvolume < 64)
                        XMC->tmpvolume = 64;
                    break;
                case 9:
                case 0xa:
                case 0xb:
                case 0xc:
                case 0xd:
                    XMC->tmpvolume += (1 << (XMC->s3mrtgslide - 9));
                    break;
                case 0xe:
                    XMC->tmpvolume = (3 * XMC->tmpvolume) / 2;
                    break;
                case 0xf:
                    XMC->tmpvolume = XMC->tmpvolume << 1;
                    break;
                }
                if (XMC->tmpvolume < 64) XMC->tmpvolume = 64;
                if (XMC->tmpvolume > 128) XMC->tmpvolume = 128;
            }
        }
        XMC->retrig--;
    }
}

/* ---------------- DoToneSlide (src/pilot/DoToneSlide.c) ---------------- */
/* Driver 2: DoToneSlide (xmplay.c) - REDRIVER2 code with abs() for ABS() */
#define ABS(x) ((x) < 0 ? -(x) : (x))
void DoToneSlide(void){ int dist;
 dist = XMC->period - XMC->wantedperiod;
 if (dist == 0 || XMC->portspeed > abs(dist)) XMC->period = XMC->wantedperiod;
 else if (dist > 0) XMC->period -= XMC->portspeed; else XMC->period += XMC->portspeed;
 XMC->tmpperiod = XMC->period; }
#undef ABS

/* ---------------- DoVibrato (src/pilot/DoVibrato.c) ---------------- */
/* Driver 2: DoVibrato */
void DoVibrato(void)
{
	unsigned char q;
	unsigned short temp = 0;
	q = (XMC->vibpos >> 2) & 0x1f;
	switch (XMC->wavecontrol & 3) {
	case 0: temp = D_0008D948[q]; break;
	case 1:
		q <<= 3;
		if (XMC->vibpos > 127) q = 255 - q;
		temp = q;
		break;
	case 2: temp = 255; break;
	}
	temp *= XMC->vibdepth;
	temp >>= 7;
	temp <<= 2;
	if (XMC->vibpos < 128)
		XMC->period = XMC->tmpperiod + temp;
	else
		XMC->period = XMC->tmpperiod - temp;
	if (D_00097814->vbtick) XMC->vibpos += XMC->vibspd;
}

/* ---------------- DoTremolo (src/pilot/DoTremolo.c) ---------------- */
/* Driver 2: DoTremolo */
void DoTremolo(void)
{
    unsigned char q;
    unsigned short temp = 0;
    q = (XMC->trmpos >> 2) & 0x1f;
    switch ((XMC->wavecontrol >> 4) & 3) {
    case 0: temp = D_0008D948[q]; break;
    case 1:
        q <<= 3;
        if (XMC->trmpos > 127) q = 255 - q;
        temp = q;
        break;
    case 2: temp = 255; break;
    }
    temp *= XMC->trmdepth;
    temp >>= 6;
    if (XMC->trmpos < 128) {
        XMC->volume = XMC->tmpvolume + temp;
        if (XMC->volume > 128) XMC->volume = 128;
    } else {
        XMC->volume = XMC->tmpvolume - temp;
        if (XMC->volume < 64) XMC->volume = 64;
    }
    if (D_00097814->vbtick) XMC->trmpos += XMC->trmspd;
}

