/* ---------------- JCalcPat (src/pilot/JCalcPat.c) ---------------- */
// JCalcPat
int JCalcPat(unsigned char *j) {
    unsigned char b;
    int ret = 1;
    b = *j;
    if (b == 0x80) return ret;
    if ((b & 0x80) != 0) {
        if ((b & 1) != 0) ret++;
        if ((b & 2) != 0) ret++;
        if ((b & 4) != 0) ret++;
        if ((b & 8) != 0) ret++;
        if ((b & 16) != 0) ret++;
    } else ret = 5;
    return ret;
}

/* ---------------- ApplyEffs (src/pilot/ApplyEffs.c) ---------------- */
/* Driver 2: ApplyEffs */
extern XMCHANNEL *XMC;
#define ms D_00097814
#define mh D_00097818
#define XMC XMC
#define ABS(x) ((x) < 0 ? -(x) : (x))
static inline short DoPan(short envpan, short pan)
{
    return (pan + (((envpan - 128) * (128 - ABS(pan - 128))) / 128));
}
static inline short DoVol(unsigned int a, short b, short c)
{
    a *= b;
    a *= c;
    a >>= 23;
    return (a);
}
void ApplyEffs(void)
{
    short envpan, envvol;
    int t;
    int pmsk;
    short vlm;
    short Pn;
    unsigned char MaxChans;

    ms->XMActiveVoices = 0;
    MaxChans = ms->MaxChans;
    for (t = 0; t < mh->XMPSXChannels; t++) {
        if (MaxChans == 0)
            return;

        pmsk = ms->PlayMask;
        pmsk &= (1 << t);
        if (pmsk != 0) {
            MaxChans--;
            XMC = (XMCHANNEL *)((char *)ms->XM_Chnl + t * 0x78);

            if (XMC->kick) {
                XMC->keyon = 1;
                XMC->fadevol = 32767;
                XMC->ChDead = 0;
            }
            if (!XMC->ChDead) {
                ms->XMActiveVoices++;

                if (XMC->period < 1)
                    XMC->period = 1;
                else if (XMC->period > 32768)
                    XMC->period = 32768;

                if (XMC->envflg & 1)
                    envvol = func_00072C18(256, XMC->keyon, XMC->sample);
                else
                    envvol = 256;
                if (XMC->panenvflg & 1)
                    envpan = func_00072E1C(128, XMC->keyon, XMC->sample);
                else
                    envpan = 128;

                vlm = XMC->volume - XMC->UserVol;
                if (vlm <= 64) {
                    XMC->LVol = XMC->RVol = 0;
                } else {
                    vlm = ((DoVol(XMC->fadevol, envvol, vlm - 64) * ms->SongVolume) / 128);

                    Pn = XMC->panning;
                    Pn += ms->UserPan;
                    if (Pn < 0)
                        Pn = 0;
                    else if (Pn > 255)
                        Pn = 255;
                    Pn = DoPan(envpan, Pn);

                    XMC->LVol = (vlm * (255 - Pn));
                    XMC->RVol = (vlm * Pn);
                }

                if ((!XMC->LVol) && (!XMC->RVol) && (!XMC->keyon)) {
                    func_000732B4(XMC->SPUChannel);
                    XMC->ChDead = 1;
                } else if (!XMC->keyon) {
                    XMC->fadevol -= XMC->keyoffspd;
                    if (XMC->fadevol < 0)
                        XMC->fadevol = 0;
                }
            }
        }
    }
}
#undef ABS
#undef XMC
#undef mh
#undef ms

