/* ---------------- DoDolbySS (src/pilot/DoDolbySS.c) ---------------- */
/* DoDolbySS */
void DoDolbySS(void)
{
    if (D_00096FA8 == 0) {
        D_00097824 = (XMC->OldLVol + XMC->OldRVol) / 2;
        D_00097820 = D_00097824;
        return;
    }
    if (XMC->Dolby == 1) {
        D_00097824 = XMC->OldLVol;
        if (XMC->OldRVol > XMC->OldLVol) {
            D_00097820 = -XMC->OldRVol;
            D_00097824 = XMC->OldRVol;
        } else
            D_00097820 = -XMC->OldRVol;
    } else if (XMC->Dolby == 2) {
        D_00097820 = XMC->OldLVol;
        if (XMC->OldRVol > XMC->OldLVol) {
            D_00097824 = -XMC->OldRVol;
            D_00097820 = XMC->OldRVol;
        } else
            D_00097824 = -XMC->OldRVol;
    } else {
        D_00097824 = XMC->OldLVol;
        D_00097820 = XMC->OldRVol;
    }
}

/* ---------------- UpdateHardware (src/pilot/UpdateHardware.c) ---------------- */
/* UpdateHardware */
void UpdateHardware(void)
{
    int t;
    int prd;
    int SPUKeyOn = 0;
    int pmsk;
    int Ch2;
    unsigned char MaxChans;

    MaxChans = D_00097814->MaxChans;
    for (t = 0; t < D_00097818->XMPSXChannels; t++) {
        if (MaxChans == 0)
            break;
        pmsk = D_00097814->PlayMask;
        pmsk &= (1 << t);
        if (pmsk != 0) {
            XMC = &D_00097814->XM_Chnl[t];
            MaxChans--;
            if (XMC->kick) {
                Ch2 = XMC->SPUChannel;
                prd = XMC->period;
                if (D_00097814->NotAmiga == 0)
                    prd = (0xA3BA68 / prd) >> 3;
                else
                    prd = GetFreq2(prd);
                SpuSetKey(0, 1 << Ch2);
                XMC->OldLVol = XMC->LVol;
                XMC->OldRVol = XMC->RVol;
                DoDolbySS();
                PlaySFX(D_00097814->VabID, Ch2, XMC->sample, prd, D_00097824, D_00097820);
                SPUKeyOn |= (1 << Ch2);
                XMC->SPUPitch = prd;
                XMC->OldPeriod = XMC->period;
            }
        }
    }
    if (SPUKeyOn != 0) {
        SpuSetKey(1, SPUKeyOn);
        SpuFlush(0);
    }

    MaxChans = D_00097814->MaxChans;
    for (t = 0; t < D_00097818->XMPSXChannels; t++) {
        if (MaxChans == 0)
            return;
        pmsk = D_00097814->PlayMask;
        pmsk &= (1 << t);
        if (pmsk != 0) {
            XMC = &D_00097814->XM_Chnl[t];
            MaxChans--;
            if (!XMC->ChDead) {
                Ch2 = XMC->SPUChannel;
                if (XMC->kick == 0) {
                    if ((XMC->LVol != XMC->OldLVol) || (XMC->RVol != XMC->OldRVol)) {
                        if (XMC->OldLVol != XMC->LVol)
                            XMC->OldLVol = IntVols(XMC->LVol, XMC->OldLVol);
                        if (XMC->OldRVol != XMC->RVol)
                            XMC->OldRVol = IntVols(XMC->RVol, XMC->OldRVol);
                        DoDolbySS();
                        ((void (*)())SetVol)(Ch2, D_00097824, D_00097820);
                    }
                    if (XMC->period != XMC->OldPeriod) {
                        XMC->OldPeriod = XMC->period;
                        prd = XMC->period;
                        if (D_00097814->NotAmiga == 0)
                            prd = (0xA3BA68 / prd) >> 3;
                        else
                            prd = GetFreq2(prd);
                        XMC->SPUPitch = prd;
                        SetFrq(Ch2, prd);
                    }
                } else
                    XMC->kick = 0;
            }
        }
    }
}

/* ---------------- IntVols (src/pilot/IntVols.c) ---------------- */
int IntVols(int a, int b)
{
    int d = b - a;
    if (d < 0)
        d = a - b;
    d >>= 1;
    d++;
    if (a < b)
        return a + d;
    return b + d;
}

/* ---------------- GetFreq2 (src/pilot/GetFreq2.c) ---------------- */
/* GetFreq2 */
int GetFreq2(int period) {
    int okt;
    period = D_00096FB4 - period;
    okt = period / 768;
    return D_0008D278[period % 768] >> (5 - okt);
}

/* ---------------- func_00072C18 (src/pilot/func_00072C18.c) ---------------- */
#define EA(b, k) ((b)[(k) * 4 + 0x81] + ((b)[(k) * 4 + 0x82] << 8))
#define EB(b, k) ((b)[(k) * 4 + 0x83] + ((b)[(k) * 4 + 0x84] << 8))
static inline short interp(int b0, int c0, int c1, unsigned short x, short a0v, short a1v)
{
    int r;
    if (a0v == a1v) {
        r = (unsigned)(b0 << 18) >> 16;
    } else {
        short dy = c1 - c0;
        short dx = x - a0v;
        r = c0 + (dx * dy) / (short)(a1v - a0v);
    }
    return r;
}
short func_00072C18(int a0, int flag, int idx)
{
    unsigned char i = *(unsigned char *)&XMC->enva;
    unsigned char j = *(unsigned char *)&XMC->envb;
    unsigned short x = XMC->envp;
    unsigned char *b = D_00097818->JAP_InstrumentOffset[idx];
    int b0 = EB(b, i);
    int c0 = b0 * 4;
    int b1 = EB(b, j);
    int c1 = b1 << 2;
    short a0v = EA(b, i);
    short a1v = EA(b, j);
    short r;

    r = interp(b0, c0, c1, x, a0v, a1v);
    if (!((XMC->envflg & 2) && (flag & 0xff) && i == XMC->envsus && x == a0v)) {
        x++;
        if (!((unsigned short)x < a1v)) {
            i = j;
            j++;
            if (XMC->envflg & 4) {
                if (XMC->envend < j) {
                    i = XMC->envbeg;
                    j = i + 1;
                    x = EA(b, i);
                }
            } else {
                if (!(j < XMC->envpts)) {
                    j--;
                    x--;
                }
            }
        }
    }
    *(unsigned short *)&XMC->enva = i;
    *(unsigned short *)&XMC->envb = j;
    XMC->envp = x;
    return r;
}
#undef EA
#undef EB

